#!/bin/bash
# Task 147-w10-units -- meshsim sim/ WORKER10 (branch sim-w10; kit: after 350c77e). TIMING TASK: keep the box quiet while it runs.
# Per-thread speed on what runs now (W10), so the units' own costs are known when the sort lands: W9's chip with W8's
# and W11's units, one thread, the sort's boot (14,791 cycles), wfi and regs (to their stop). Plain (bench_chip --reps 9,
# 3 processes); --units (each unit kind's time and ns a step, calibrating, the clock's cost taken off; 3 runs); perf
# record's top symbols. One revision (350c77e). ~2 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/147-w10-units/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/147-w10-units; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-147-w10-units; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "62506e3a00fc1c2036ad560672a774084f70933e754123a83cda75a753e100f7" ] || { echo "kit sha256 mismatch (want 62506e3a00fc1c2036ad560672a774084f70933e754123a83cda75a753e100f7)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after 350c77e"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): per-thread speed on what runs now (W9's chip with W8's and W11's units): the sort's boot, wfi and
# regs (both to their stop) on one thread. (1) plain, bench_chip --reps 9, 3 processes; (2) --units: each unit kind's
# time per cycle, steps per cycle and ns a step (a calibrating run, the clock's own cost taken off), 3 processes;
# (3) perf record on a plain run (top symbols), where perf may record.
sec "build (clang release, D18)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_chip > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
P1=$(take 1 "$P_ONE")
crun() { local tag=$1 cpus=$2 k=$3; shift 3; ( cd "$W/kit/$k/sim" && run "$tag" "$cpus" ./build/clang-release/bench_chip "$@" ); }
for rep in 1 2 3; do for k in $KITS; do for p in sort wfi regs; do
  crun "$k plain-$p" "$P1" $k --prog $p --threads 1 --cpus "$P1" --reps 9
  ( cd "$W/kit/$k/sim" && taskset -c "$P1" ./build/clang-release/bench_chip --prog $p --units > "$RES/units-$k-$p-$rep.txt" 2>&1 ) || echo "RUNFAIL units $p"
done; done; done
sec "perf record (top symbols, self time), one plain run each"
for k in $KITS; do for p in sort wfi regs; do
  ( cd "$W/kit/$k/sim" && taskset -c "$P1" perf record -q -o "$W/perf-$p.data" -- ./build/clang-release/bench_chip --prog $p --reps 9 > /dev/null 2>&1 \
    && perf report -i "$W/perf-$p.data" --stdio --no-children --percent-limit 0.7 --sort symbol 2>/dev/null | grep -v '^#' | grep -v '^$' | head -45 \
       > "$RES/perf-$k-$p.txt" ) || echo "perf record not available for $p" > "$RES/perf-$k-$p.txt"
  echo "== perf $p"; head -45 "$RES/perf-$k-$p.txt"
done; done
sec "digests"
for key in "chip prog=sort" "chip prog=wfi" "chip prog=regs"; do
  n=$(grep -E "$key" "$RES/raw.txt" | field digest | sort -u | wc -l); [ "$n" = 1 ] && verdict "digests ($key)" PASS || verdict "digests ($key): $n distinct" FAIL
done
sec "summary: one thread us per cycle (medians of the processes' medians); the units by kind (3 runs each)"
for k in $KITS; do for p in sort wfi regs; do
  echo "$k $p: one thread us_per_cycle $(grep "^$k plain-$p " "$RES/raw.txt" | field us_per_cycle | paste -sd' ')"
  for rep in 1 2 3; do head -1 "$RES/units-$k-$p-$rep.txt"; done
  echo "  by kind (run 1; runs 2, 3 in units-*.txt):"; grep '^unit ' "$RES/units-$k-$p-1.txt" | head -16 | sed 's/^/  /'
done; done | tee "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
